import { test, expect, Page } from '@playwright/test';

test.describe('Cookie Consent Banner', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display cookie consent banner on page load', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const title = page.getByRole('heading', { name: /cookie consent/i });
    await expect(title).toBeVisible();

    const description = page.getByText(/we use cookies to enhance your experience/i);
    await expect(description).toBeVisible();
  });

  test('should hide banner after accepting cookies', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const acceptButton = page.getByRole('button', { name: /accept/i });
    await expect(acceptButton).toBeVisible();

    await acceptButton.click();

    await expect(banner).not.toBeVisible();
  });

  test('should hide banner after rejecting cookies', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const rejectButton = page.getByRole('button', { name: /reject/i });
    await expect(rejectButton).toBeVisible();

    await rejectButton.click();

    await expect(banner).not.toBeVisible();
  });

  test('should persist cookie acceptance and not show banner on reload', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    const acceptButton = page.getByRole('button', { name: /accept/i });

    await acceptButton.click();
    await expect(banner).not.toBeVisible();

    await page.reload();

    await expect(banner).not.toBeVisible();
  });

  test('should have accessible close button on banner', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const closeButton = page.getByRole('button', { name: /close|dismiss/i });
    await expect(closeButton).toBeVisible();

    await closeButton.click();

    await expect(banner).not.toBeVisible();
  });

  test('should display all required cookie options before accepting', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const essentialCheckbox = page.getByLabel(/essential|necessary/i);
    await expect(essentialCheckbox).toBeVisible();

    const analyticsCheckbox = page.getByLabel(/analytics|performance/i);
    await expect(analyticsCheckbox).toBeVisible();

    const marketingCheckbox = page.getByLabel(/marketing|advertising/i);
    await expect(marketingCheckbox).toBeVisible();
  });

  test('should allow customizing cookie preferences before accepting', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).toBeVisible();

    const preferencesButton = page.getByRole('button', { name: /preferences|customize/i });
    await expect(preferencesButton).toBeVisible();

    await preferencesButton.click();

    const analyticsCheckbox = page.getByLabel(/analytics|performance/i);
    await analyticsCheckbox.uncheck();

    const saveButton = page.getByRole('button', { name: /save|confirm/i });
    await saveButton.click();

    await expect(banner).not.toBeVisible();
  });

  test('should have proper focus management when banner appears', async () => {
    const acceptButton = page.getByRole('button', { name: /accept/i });

    const focusedElement = await page.evaluate(() => {
      return document.activeElement?.getAttribute('aria-label') || 
             document.activeElement?.textContent;
    });

    await acceptButton.focus();
    const isFocused = await acceptButton.evaluate(el => el === document.activeElement);
    expect(isFocused).toBe(true);

    await acceptButton.click();

    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    await expect(banner).not.toBeVisible();
  });

  test('should handle rapid accept button clicks gracefully', async () => {
    const banner = page.getByRole('dialog', { name: /cookie consent/i });
    const acceptButton = page.getByRole('button', { name: /accept/i });

    await acceptButton.click();
    await acceptButton.click();

    await expect(banner).not.toBeVisible();
  });
});
